/** MTV `Locale`（`zh-CN` 等）→ 本表键（`zhCN` 等）。（MTV `getLocale()` 返回 `zh-CN`，而表键是 `zhCN`，
 *  此前直接用 `locale` 索引导致**恒 miss、恒返回 key**，官方 zh 文案取不到。） */
const LOCALE_TABLE_KEY: Record<string, string> = {
  'zh-CN': 'zhCN', zhCN: 'zhCN', zh: 'zhCN',
  'en-US': 'enUS', enUS: 'enUS', en: 'enUS',
  'ja-JP': 'jaJP', jaJP: 'jaJP', ja: 'jaJP',
  'ko-KR': 'koKR', koKR: 'koKR', ko: 'koKR',
};

/** 取官方 `chatAdapter.agentEvent.<key>`（支持 `a.b.c` 路径；未知回落英文/原样返回）。 */
export function agentEventString(path: string, locale = 'zh-CN'): string {
  const read = (table: Record<string, unknown>): string | null => {
    let node: unknown = table;
    for (const part of path.split('.')) {
      if (!node || typeof node !== 'object') return null;
      node = (node as Record<string, unknown>)[part];
    }
    return typeof node === 'string' ? node : null;
  };
  const key = LOCALE_TABLE_KEY[locale] ?? 'zhCN';
  return read(AGENT_EVENT_STRINGS[key] ?? {})
    ?? read(AGENT_EVENT_STRINGS.enUS ?? {})
    ?? path;
}